import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Networking — The Open Internet Toolbox","description":"TCP/IP, DNS, proxies, VLESS tunnels, edge networks — deep practical networking for hostile environments.","frontmatter":{"title":"Networking — The Open Internet Toolbox","description":"TCP/IP, DNS, proxies, VLESS tunnels, edge networks — deep practical networking for hostile environments."},"headers":[],"relativePath":"en/skills/networking/index.md","filePath":"en/skills/networking/index.md"}`),a={name:`en/skills/networking/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="networking-—-the-open-internet-toolbox" tabindex="-1">Networking — The Open Internet Toolbox <a class="header-anchor" href="#networking-—-the-open-internet-toolbox" aria-label="Permalink to “Networking — The Open Internet Toolbox”">​</a></h1><p>Networking is my specialty under pressure: I build for networks that actively fight back. That means fluency from packets to platforms — how a TLS handshake dies, why a subscription link breaks, where a tunnel leaks DNS.</p><h2 id="competence-map" tabindex="-1">Competence map <a class="header-anchor" href="#competence-map" aria-label="Permalink to “Competence map”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Skills</th></tr></thead><tbody><tr><td>Fundamentals</td><td>TCP/IP, DNS, HTTP/2–3, TLS, routing, NAT, capture analysis</td></tr><tr><td>Proxy tech</td><td>VLESS, VMess, Trojan, Reality; Clash, v2ray, sing-box configs</td></tr><tr><td>Edge &amp; CDN</td><td>Cloudflare Workers, KV, 300+ PoP distribution, WAF rules</td></tr><tr><td>Diagnostics</td><td>Port scanning, TCP ping, TLS inspection (<a href="/Usf/en/projects/netpilot/">NetPilot</a>)</td></tr><tr><td>Operations</td><td>Multi-platform redundancy, zero-downtime migrations</td></tr></tbody></table><p>This is the domain where my <a href="/Usf/en/projects/usf-panel/">panel family</a> lives, and it shapes everything else: my API bridges assume throttling, my routers assume upstream death, and my deploys assume any single platform can disappear overnight. Redundancy is not paranoia — it is the baseline SLA of a free and open connection.</p><blockquote><p>A network you can trust is built, not hoped for.</p></blockquote>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};